import { supabaseClient } from './supabase-client.js';

const $=id=>document.getElementById(id);
const esc=(v='')=>String(v).replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
const validEditions=new Set(['basic','expert']);
const params=new URLSearchParams(location.search);
let edition=String(params.get('edition')||'').toLowerCase();
if(!validEditions.has(edition)){try{edition=String(localStorage.getItem('aclSelectedEdition')||'expert').toLowerCase()}catch{edition='expert'}}
if(!validEditions.has(edition))edition='expert';
try{localStorage.setItem('aclSelectedEdition',edition)}catch{}

const grid=$('modules'),status=$('modulesStatus'),summary=$('catalogueSummary'),search=$('moduleSearchInputCompact'),availability=$('moduleAvailabilityCompact'),progressFilter=$('moduleProgressCompact'),searchSummary=$('moduleSearchSummary'),clear=$('clearModuleFiltersCompact');
let modules=[],attempts=[],assigned=new Set(),profile=null;

function show(msg='',kind=''){if(!status)return;status.textContent=msg;status.className=`status-box ${kind}`.trim();status.hidden=!msg;}
function launch(m){if(!m.launch_path)return'';try{const u=new URL(m.launch_path,location.href);u.searchParams.set('edition',edition);return u.origin===location.origin?`${u.pathname}${u.search}${u.hash}`:u.toString()}catch{return''}}
function latestAttempt(id){return attempts.find(a=>String(a.module_id)===String(id))||null}
function decision(m){const st=String(m.status||'').toLowerCase(),access=String(m.access_type||'').toLowerCase();if(st==='coming_soon'||st==='draft')return{state:'coming',label:'Coming soon'};if(!m.launch_path)return{state:'coming',label:'Coming soon'};if(access==='subscription'&&!assigned.has(m.id))return{state:'locked',label:'Subscription required'};if(access==='admin_assigned'&&!assigned.has(m.id))return{state:'locked',label:'Assignment required'};return{state:'open',label:'Open module'}}
function theme(m){const t=[m.title,m.category,m.slug].filter(Boolean).join(' ').toLowerCase();if(/ecg|rhythm|arrhythm/.test(t))return['module-ecg','Electrocardiography'];if(/echo|imaging|ct|mri|cmr/.test(t))return['module-imaging','Imaging'];if(/pci|tavi|intervention|mitral|tricuspid|cto|left main/.test(t))return['module-intervention','Interventional Cardiology'];return['module-general','General Cardiology']}
function card(m){const d=decision(m),a=latestAttempt(m.id),completed=a?.status==='completed',inProgress=a?.status==='in_progress',href=d.state==='open'?launch(m):'',t=theme(m);const action=inProgress?'Continue module':completed?'Review / retry':d.label;return `<article class="module-card ${t[0]} ${d.state}" data-module-id="${esc(m.id)}"><div class="module-cover"><span class="module-category">${esc(t[1])}</span></div><div class="module-card-body"><div class="module-card-heading"><h2>${esc(m.title||'ACL module')}</h2>${m.difficulty?`<span class="difficulty-pill">${esc(m.difficulty)}</span>`:''}</div><p>${esc(m.short_description||m.description||'ACL Expert learning module')}</p><div class="module-meta"><span>⏱ ${Number(m.estimated_minutes||0)} min</span><span>❓ ${Number(m.question_count||0)} questions</span></div>${a?`<div class="module-progress-line"><span>${inProgress?'In progress':completed?'Completed':esc(a.status||'Attempted')}</span><strong>${Number(a.score||0)} pts</strong></div>`:''}<div class="module-card-actions"><a class="module-action ${href?'':'disabled'}" href="${href?esc(href):'#'}" ${href?'':'aria-disabled="true" tabindex="-1"'}>${esc(action)}</a></div></div></article>`}
function filterModules(){const term=String(search?.value||'').trim().toLowerCase(),av=availability?.value||'all',pf=progressFilter?.value||'all';const rows=modules.filter(m=>{const d=decision(m),a=latestAttempt(m.id),text=[m.title,m.short_description,m.description,m.category,m.slug].filter(Boolean).join(' ').toLowerCase();const matchText=!term||text.includes(term);const matchAv=av==='all'||(av==='open'?d.state==='open':av==='locked'?d.state!=='open':av==='subscription'?String(m.access_type||'').toLowerCase()==='subscription':true);const state=a?.status||'not-started';const matchProg=pf==='all'||(pf==='not-started'?!a:pf==='started'?state==='in_progress':pf==='completed'?state==='completed':true);return matchText&&matchAv&&matchProg});grid.innerHTML=rows.length?rows.map(card).join(''):'<div class="module-filter-empty"><strong>No matching modules found</strong><p>Try changing the search or filters.</p></div>';if(searchSummary)searchSummary.textContent=`${rows.length} of ${modules.length} modules shown`;if(summary)summary.textContent=`${modules.length} modules · ${attempts.filter(a=>a.status==='completed').length} completed attempts`;show('');renderContinue(rows);}
function renderContinue(source=modules){const host=$('aclContinueLearning');if(!host)return;const candidates=source.map(m=>({m,a:latestAttempt(m.id)})).filter(x=>x.a?.status==='in_progress').slice(0,3);const fall=candidates.length?candidates:source.filter(m=>decision(m).state==='open').slice(0,3).map(m=>({m,a:latestAttempt(m.id)}));host.innerHTML=fall.length?fall.map(({m,a})=>{const href=launch(m),pct=a?.status==='completed'?100:a?.status==='in_progress'?55:0;return `<article class="acl-continue-card"><div class="acl-continue-card-top"><div class="acl-continue-icon">♡</div><div class="acl-continue-copy"><h3>${esc(m.title)}</h3><small>${a?.status==='in_progress'?'In progress':a?.status==='completed'?'Completed':'Not started'}</small></div><strong class="acl-continue-percent">${pct}%</strong></div><div class="acl-continue-progress"><span style="width:${pct}%"></span></div><a href="${esc(href)}">›</a></article>`}).join(''):'<div class="card muted">No open modules yet.</div>'}
async function safeQuery(promise,fallback){try{const r=await promise;if(r.error)throw r.error;return r.data??fallback}catch(e){console.warn('ACL optional catalogue query failed',e);return fallback}}
async function load(){show('Loading your ACL catalogue…');try{const{data:{session},error:sErr}=await supabaseClient.auth.getSession();if(sErr||!session?.user){location.replace('login.html');return}const user=session.user;profile=await safeQuery(supabaseClient.from('profiles').select('*').eq('id',user.id).maybeSingle(),{});const core=await supabaseClient.from('modules').select('*').eq('edition',edition).order('display_order',{ascending:true}).order('title',{ascending:true});if(core.error)throw core.error;modules=Array.isArray(core.data)?core.data:[];grid.innerHTML=modules.length?modules.map(card).join(''):'<div class="empty-state">No modules are currently available in this edition.</div>';if(summary)summary.textContent=`${modules.length} modules`;if(searchSummary)searchSummary.textContent=`${modules.length} modules available`;renderContinue(modules);show('');const [aRows,assignRows]=await Promise.all([safeQuery(supabaseClient.from('quiz_attempts').select('module_id,status,score,updated_at').eq('user_id',user.id).order('updated_at',{ascending:false}),[]),safeQuery(supabaseClient.from('module_assignments').select('module_id,expires_at').eq('user_id',user.id),[])]);attempts=Array.isArray(aRows)?aRows:[];assigned=new Set((Array.isArray(assignRows)?assignRows:[]).filter(x=>!x.expires_at||new Date(x.expires_at).getTime()>Date.now()).map(x=>x.module_id));filterModules();}catch(e){console.error('ACL FAIL-SAFE MODULE LOAD',e);grid.innerHTML='<div class="empty-state"><strong>Could not load the module catalogue.</strong><p>Please refresh once. If this persists, the database connection is unavailable.</p></div>';if(summary)summary.textContent='Catalogue unavailable';if(searchSummary)searchSummary.textContent='Unable to load modules';show(e.message||'Could not load modules.','error')}}
search?.addEventListener('input',filterModules);availability?.addEventListener('change',filterModules);progressFilter?.addEventListener('change',filterModules);clear?.addEventListener('click',()=>{if(search)search.value='';if(availability)availability.value='all';if(progressFilter)progressFilter.value='all';filterModules()});
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',load,{once:true});else load();
